 node=next(n for n in ast.parse(raw).body if isinstance(n,ast.FunctionDef)and n.name=='_attrs');scope=dict(vars(observer));exec(compile(ast.Module(body=[node],type_ignores=[]),'file_capabilities-scoped.py','exec'),scope)
